**Informations opérationnelles :**
```javascript
getActiveOperations() {
    const now = Date.now();

    return {
        intervals: Array.from(this.intervals.entries()).map(([name, info]) => ({
            name,
            interval: info.interval,
            runningTime: now - info.startTime,
            errorCount: this.errorCounts.get(name) || 0
        })),
        timeouts: Array.from(this.timeouts.entries()).map(([name, info]) => ({
            name,
            delay: info.delay,
            timeRemaining: Math.max(0, (info.startTime + info.delay) - now)
        })),
        totalIntervals: this.intervals.size,
        totalTimeouts: this.timeouts.size
    };
}
```

## 🔄 Intégration AppState

**Polling pour mise à jour Timeline :**
```javascript
import { pollingManager } from './utils/PollingManager.js';
import { appState } from './state/AppState.js';

// Polling état workflow
function pollWorkflowStatus() {
    return fetch('/api/workflow/status')
        .then(response => response.json())
        .then(data => {
            // Mise à jour AppState
            appState.setState({
                steps: data.steps,
                sequence: data.sequence
            });

            // Backoff si séquence inactive
            if (!data.sequence.is_running) {
                return 30000;  // Pause 30s
            }
        })
        .catch(error => {
            console.error('Workflow polling error:', error);
            throw error;
        });
}

// Démarrage polling
const pollingId = pollingManager.startPolling(
    'workflow-status',     // Nom unique
    pollWorkflowStatus,    // Callback
    5000,                  // Interval 5s
    { 
        immediate: true,     // Appel immédiat
        maxErrors: 3         // Arrêt après 3 erreurs
    }
);
```

## 📡 Événements Custom

**Propagation erreurs polling :**
```javascript
_dispatchPollingError(name, error, errorCount) {
    const event = new CustomEvent('pollingError', {
        detail: {
            name,
            error,
            errorCount,
            timestamp: new Date().toISOString()
        }
    });

    window.dispatchEvent(event);
}

// Écoute événements dans autres modules
window.addEventListener('pollingError', (event) => {
    const { name, error, errorCount } = event.detail;
    console.warn(`Polling failed: ${name}, attempt ${errorCount}`);

    // Actions correctives
    showErrorNotification(`Polling ${name} failed after ${errorCount} attempts`);
});
```

