function handleShowSpecificLogs(event) {
    event.preventDefault();

    const button = event.target.closest('.specific-log-button');
    if (!button) return;

    const stepKey = button.dataset.step;
    if (!isValidStepKey(stepKey)) {
        console.error(`Invalid step key: ${stepKey}`);
        return;
    }

    // Feedback visuel immédiat
    button.disabled = true;
    button.textContent = 'Chargement...';

    try {
        // Récupération logs
        const logs = await fetchStepLogs(stepKey);

        // Affichage
        showLogsOverlay(stepKey, logs);

    } catch (error) {
        console.error(`Failed to load logs for ${stepKey}:`, error);
        showErrorToast('Erreur lors du chargement des logs');

    } finally {
        // Reset UI
        button.disabled = false;
        button.textContent = 'Voir logs';
    }
}
```

