function handleKeyboardNavigation(event) {
    // Raccourcis globaux
    switch (event.key) {
        case 'Escape':
            handleEscapeKey(event);
            break;
        case 'F1':
            event.preventDefault();
            showHelpOverlay();
            break;
        case 'r':
            if (event.ctrlKey) {
                event.preventDefault();
                refreshWorkflowStatus();
            }
            break;
    }

    // Navigation focus
document.querySelectorAll('[tabindex]').forEach(element => {
        if (element === event.target) {
            handleFocusNavigation(element, event);
        }
    });
}

function handleEscapeKey(event) {
    // Fermeture overlays actifs
    if (isLogsOverlayOpen()) {
        hideLogsOverlay();
        event.preventDefault();
        return;
    }

    if (isSettingsPanelOpen()) {
        hideSettingsPanel();
        event.preventDefault();
        return;
    }

    // Désélection séquence personnalisée
    clearCustomSequenceSelection();
}
```

## 🚨 Gestion Erreurs Globales

**Handlers erreurs non capturées :**
```javascript
function handleGlobalError(event) {
    console.error('Global error:', event.error);

    // Logging détaillé
    logError({
        type: 'global_error',
        message: event.message,
        filename: event.filename,
        lineno: event.lineno,
        colno: event.colno,
        error: event.error,
        timestamp: new Date().toISOString()
    });

    // Feedback utilisateur
    showErrorToast('Une erreur inattendue s\'est produite');

    // Recovery si possible
    attemptErrorRecovery(event);
}

function handleUnhandledRejection(event) {
    console.error('Unhandled promise rejection:', event.reason);

    // Logging
    logError({
        type: 'unhandled_rejection',
        reason: event.reason,
        timestamp: new Date().toISOString()
    });

    // Feedback
    showErrorToast('Erreur asynchrone non gérée');

    // Prévention comportement par défaut
    event.preventDefault();
}
```

