// Cache des éléments (faible TTL pour éviter stale references)
let _elementCache = new Map();
const CACHE_TTL = 5000; // 5 secondes

class CachedElementGetter {
    static getElementById(id, ttl = CACHE_TTL) {
        const key = `id:${id}`;
        const cached = _elementCache.get(key);

        if (cached && (Date.now() - cached.timestamp) < ttl) {
            if (cached.element && document.contains(cached.element)) {
                return cached.element;
            }
        }

        const element = document.getElementById(id);
        if (element) {
            _elementCache.set(key, {
                element: element,
                timestamp: Date.now()
            });
        }

        return element;
    }

    static invalidateCache() {
        _elementCache.clear();
    }
}

export function getCachedAppContainer() {
    return CachedElementGetter.getElementById('app');
}
