export function safeGetElement(selector) {
    try {
        if (typeof selector === 'string') {
            return document.querySelector(selector);
        } else if (selector instanceof Element) {
            return selector;
        } else if (typeof selector === 'function') {
            return selector();
        }
        return null;
    } catch (error) {
        console.error(`Error getting element with selector ${selector}:`, error);
        return null;
    }
}

export function safeGetElements(selector) {
    try {
        const elements = document.querySelectorAll(selector);
        return Array.from(elements);
    } catch (error) {
        console.error(`Error getting elements with selector ${selector}:`, error);
        return [];
    }
}
