        updateLogsCounter(stepKey, countLogLines(logsContent));
    });
}

function parseAndStyleLogContent(rawLogs, options) {
    if (!rawLogs) return '';

    // Limitation lignes
const lines = rawLogs.split('\n');
    const limitedLines = lines.slice(-options.maxLines);

    // Parsing et styling
    return limitedLines.map(line => {
        // Échappement sécurité
        const escaped = DOMUpdateUtils.escapeHtml(line);

        // Highlight erreurs
        if (options.highlightErrors && isErrorLine(line)) {
            return `<div class="log-line log-error">${escaped}</div>`;
        }

        // Highlight succès
        if (isSuccessLine(line)) {
            return `<div class="log-line log-success">${escaped}</div>`;
        }

        return `<div class="log-line">${escaped}</div>`;
    }).join('');
}
