## 🌐 Fonction de Requête Générique

**Gestion complète HTTP :**
```javascript
async function apiRequest(endpoint, options = {}) {
    const {
        method = 'GET',
        params = {},
        timeout = API_TIMEOUTS.DEFAULT,
        retries = 2,
        retryDelay = 1000
    } = options;

    // Construction URL avec paramètres
    const url = buildApiUrl(endpoint, params);

    const requestOptions = {
        method,
        headers: {
            'Content-Type': 'application/json',
            'X-Requested-With': 'XMLHttpRequest'
        },
        signal: AbortSignal.timeout(timeout)
    };

    // Retry logic
    for (let attempt = 0; attempt <= retries; attempt++) {
        try {
            const response = await fetch(url, requestOptions);

            if (!response.ok) {
                throw new ApiError(
                    `HTTP ${response.status}: ${response.statusText}`,
                    response.status,
                    await response.text()
                );
            }

            const data = await response.json();
            return data;

        } catch (error) {
            const isLastAttempt = attempt === retries;

            if (isRetryableError(error) && !isLastAttempt) {
                console.warn(`API request failed (attempt ${attempt + 1}), retrying...`, error);
                await delay(retryDelay * (attempt + 1)); // Backoff exponentiel
                continue;
            }

            throw transformApiError(error);
        }
    }
}
```

## 🔧 Construction URLs et Paramètres

**Gestion paramètres complexes :**
```javascript
function buildApiUrl(endpoint, params = {}) {
    const baseUrl = window.location.origin;
    let url = `${baseUrl}${endpoint}`;

    // Gestion paramètres query
const queryParams = new URLSearchParams();

    Object.entries(params).forEach(([key, value]) => {
        if (value !== null && value !== undefined) {
            if (Array.isArray(value)) {
                // Arrays : param[]=val1&param[]=val2
                value.forEach(item => queryParams.append(`${key}[]`, item));
            } else if (typeof value === 'object') {
                // Objects : param[key]=value
                Object.entries(value).forEach(([subKey, subValue]) => {
                    queryParams.append(`${key}[${subKey}]`, subValue);
                });
            } else {
                queryParams.append(key, value);
            }
        }
    });

    const queryString = queryParams.toString();
    if (queryString) {
        url += `?${queryString}`;
    }

    return url;
}
```

## 🚨 Gestion d'Erreurs

**Transformation erreurs API :**
```javascript
class ApiError extends Error {
    constructor(message, status, responseText) {
        super(message);
        this.name = 'ApiError';
        this.status = status;
        this.responseText = responseText;
    }
}

function transformApiError(error) {
    if (error instanceof ApiError) {
        return error;
    }

    if (error.name === 'AbortError') {
        return new ApiError('Request timeout', 408, '');
    }

    if (error.name === 'TypeError' && error.message.includes('fetch')) {
        return new ApiError('Network error', 0, '');
    }

    return new ApiError(`Request failed: ${error.message}`, 0, '');
}

function isRetryableError(error) {
    // Retry sur erreurs réseau et timeouts
    return error.name === 'TypeError' || 
           error.name === 'AbortError' || 
           (error instanceof ApiError && error.status >= 500);
}
```

